Lemma ap_B : forall (fx : FPState) regs (m : word -> option byte) (s pixs pixd datas wpls datad wpld w h : Z),
  (4096 + 96 <= s <= 2 ^ 47)%Z ->
  (4096 <= pixs)%Z ->
  (pixs + 64 <= s - 96)%Z ->
  (4096 <= pixd)%Z ->
  (pixd + 64 <= s - 96)%Z ->
  (0 <= datas < 2 ^ 64)%Z ->
  (0 <= wpls < 2 ^ 31)%Z ->
  (0 <= datad < 2 ^ 64)%Z ->
  (0 <= wpld < 2 ^ 31)%Z ->
  (0 <= w < 2 ^ 31)%Z ->
  (1 <= h < 2 ^ 31)%Z ->
  rdn SEGS m (Z_to_bv 64 (pixs + 56)) 8 = Some (Z_to_le_bytes 8 datas) ->
  rdn SEGS m (Z_to_bv 64 (pixs + 16)) 4 = Some (Z_to_le_bytes 4 wpls) ->
  rdn SEGS m (Z_to_bv 64 (pixd + 56)) 8 = Some (Z_to_le_bytes 8 datad) ->
  rdn SEGS m (Z_to_bv 64 (pixd + 16)) 4 = Some (Z_to_le_bytes 4 wpld) ->
  rdn SEGS m (Z_to_bv 64 pixs) 4 = Some (Z_to_le_bytes 4 w) ->
  rdn SEGS m (Z_to_bv 64 (pixs + 4)) 4 = Some (Z_to_le_bytes 4 h) ->
  store_ok SEGS m (Z_to_bv 64 (s - 96)) 96 = true ->
  getr regs 2 = Z_to_bv 64 (s - 96) ->
  getr regs 10 = Z_to_bv 64 pixd ->
  getr regs 19 = Z_to_bv 64 pixs ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 188564) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 188652) M' rom /\
      rinv [((s - 96)%Z, 8%Z)] m M' /\
      rdn SEGS M' (Z_to_bv 64 (s - 92)) 4 = Some (Z_to_le_bytes 4 w) /\ rdn SEGS M' (Z_to_bv 64 (s - 96)) 4 = Some (Z_to_le_bytes 4 h) /\
      getr regs' 2 = Z_to_bv 64 (s - 96) /\ getr regs' 8 = Z_to_bv 64 pixd /\ getr regs' 9 = Z_to_bv 64 datas /\ getr regs' 18 = Z_to_bv 64 datad /\
      getr regs' 20 = Z_to_bv 64 wpls /\ getr regs' 21 = Z_to_bv 64 wpld /\ getr regs' 10 = Z_to_bv 64 0 /\
