Lemma ap_Bn : forall (fx : FPState) regs (m : word -> option byte) (s : Z) (v1 v8 v9 v18 v19 v20 v21 v22 v23 v24 v25 : word),
  (4096 + 96 <= s <= 2 ^ 47)%Z ->
  (438272 <= s - 96)%Z ->
  (forall j, (230424 <= j < 230584)%Z -> m (Z_to_bv 64 j) = None) ->
  (forall j, (234720 <= j < 234728)%Z -> m (Z_to_bv 64 j) = None) ->
  rdn SEGS m (Z_to_bv 64 (s - 8)) 8 = Some (word_to_le_bytes 8 v1) ->
  rdn SEGS m (Z_to_bv 64 (s - 16)) 8 = Some (word_to_le_bytes 8 v8) ->
  rdn SEGS m (Z_to_bv 64 (s - 24)) 8 = Some (word_to_le_bytes 8 v9) ->
  rdn SEGS m (Z_to_bv 64 (s - 32)) 8 = Some (word_to_le_bytes 8 v18) ->
  rdn SEGS m (Z_to_bv 64 (s - 40)) 8 = Some (word_to_le_bytes 8 v19) ->
  rdn SEGS m (Z_to_bv 64 (s - 48)) 8 = Some (word_to_le_bytes 8 v20) ->
  rdn SEGS m (Z_to_bv 64 (s - 56)) 8 = Some (word_to_le_bytes 8 v21) ->
  rdn SEGS m (Z_to_bv 64 (s - 64)) 8 = Some (word_to_le_bytes 8 v22) ->
  rdn SEGS m (Z_to_bv 64 (s - 72)) 8 = Some (word_to_le_bytes 8 v23) ->
  rdn SEGS m (Z_to_bv 64 (s - 80)) 8 = Some (word_to_le_bytes 8 v24) ->
  rdn SEGS m (Z_to_bv 64 (s - 88)) 8 = Some (word_to_le_bytes 8 v25) ->
  getr regs 2 = Z_to_bv 64 (s - 96) ->
  getr regs 10 = Z_to_bv 64 0 ->
  reach SEGS (@mkst fx regs (Z_to_bv 64 188564) m rom)
    (fun fin => exists regs' M', fin = @mkst fx regs' (Z_to_bv 64 97396) M' rom /\
      M' = m /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 10 = Z_to_bv 64 67416 /\ getr regs' 11 = Z_to_bv 64 70785 /\ getr regs' 12 = Z_to_bv 64 0 /\
      getr regs' 1 = v1 /\ getr regs' 8 = v8 /\ getr regs' 9 = v9 /\ getr regs' 18 = v18 /\ getr regs' 19 = v19 /\ getr regs' 20 = v20 /\ getr regs' 21 = v21 /\ getr regs' 22 = v22 /\ getr regs' 23 = v23 /\ getr regs' 24 = v24 /\ getr regs' 25 = v25 /\
      regs_agree (fun r => In r [1; 2; 8; 9; 10; 11; 12; 18; 19; 20; 21; 22; 23; 24; 25]%list) regs regs').
Proof.
